-- Lưu địa chỉ cũ trước sáp nhập vào legacy_address UPDATE household SET legacy_address = concat_ws(', ', nullif(trim(concat_ws(' ', house_number, alley, street)), ''), hamlet, 'Huyện Hóc Môn, TP.HCM' ) WHERE legacy_address IS NULL;
-- Khớp tự động hamlet_id theo tên ấp hiện có UPDATE household h SET hamlet_id = hm.id FROM hamlet hm WHERE h.hamlet_id IS NULL AND ( lower(trim(h.hamlet)) = lower(trim(hm.full_name)) OR lower(trim(replace(h.hamlet, 'Ấp ', ''))) = lower(trim(hm.name)) OR lower(trim(replace(h.hamlet, 'ấp ', ''))) = lower(trim(hm.name)) );
-- Dự phòng: Nếu bản ghi nào chưa khớp (ví dụ dữ liệu mẫu cũ), gán vào Ấp Bắc Lân (id=1) UPDATE household SET hamlet_id = 1 WHERE hamlet_id IS NULL;
-- Tạo View địa chỉ chuẩn hóa cho hộ dân CREATE OR REPLACE VIEW v_household_address AS SELECT h.id AS household_id, h.code AS household_code, h.house_number, h.street, h.alley, h.neighborhood_group, h.legacy_address, hm.id AS hamlet_id, hm.code AS hamlet_code, hm.name AS hamlet_name, hm.full_name AS hamlet_full_name, c.id AS commune_id, c.code AS commune_code, c.name AS commune_name, c.full_name AS commune_full_name, p.id AS province_id, p.code AS province_code, p.name AS province_name, p.full_name AS province_full_name, concat_ws(', ', nullif(trim(concat_ws(' ', h.house_number, h.alley, h.street)), ''), nullif(trim(h.neighborhood_group), ''), hm.full_name, c.full_name, p.full_name ) AS full_address_standard FROM household h LEFT JOIN hamlet hm ON hm.id = h.hamlet_id LEFT JOIN admin_commune c ON c.id = hm.commune_id LEFT JOIN admin_province p ON p.id = c.province_id;
